#include "ar_loudness.h"

static const int N = 512;
static void feed(std::vector<float>& sig) {   // whole frames only
  for (size_t i = 0; i + N <= sig.size(); i += N) arLoudnessProcess(&sig[i], N);
}
static std::vector<float> sine(double fs, double f, double dbfs, double secs, double ph = 0) {
  std::vector<float> v((size_t)(fs * secs));
  const double a = 32767.0 * pow(10.0, dbfs / 20.0);
  for (size_t i = 0; i < v.size(); i++) v[i] = (float)(a * sin(2 * M_PI * f * i / fs + ph));
  return v;
}
// |H| of the module's fixed K-weighting at frequency f, if run at sample rate fs.
static double kwDb(double f, double fs) {
  std::complex<double> z = std::polar(1.0, -2 * M_PI * f / fs), z2 = z * z;
  auto h = [&](double b0, double b1, double b2, double a1, double a2) {
    return (b0 + b1 * z + b2 * z2) / (1.0 + a1 * z + a2 * z2); };
  auto H = h(AR_KW_HS_B0, AR_KW_HS_B1, AR_KW_HS_B2, AR_KW_HS_A1, AR_KW_HS_A2) *
           h(AR_KW_HP_B0, AR_KW_HP_B1, AR_KW_HP_B2, AR_KW_HP_A1, AR_KW_HP_A2);
  return 20 * log10(std::abs(H));
}
